mapper.select:
SELECT * FROM train_command_proposal
WHERE actor_user_id = #{actorUserId}
ORDER BY created_at DESC, proposal_id

mapper.update:
UPDATE train_command_proposal
SET status = 'EXECUTED', decided_at = #{decidedAt}
WHERE proposal_id = #{proposalId} AND status = 'PENDING'

UPDATE train_command_proposal
SET status = 'REJECTED', decided_at = #{decidedAt}
WHERE proposal_id = #{proposalId} AND status = 'PENDING'

UPDATE train_command_proposal
SET exit_code = #{exitCode}, stdout = #{stdout}, stderr = #{stderr}, executed_at = #{executedAt}
WHERE proposal_id = #{proposalId} AND status = 'EXECUTED' AND exit_code IS NULL

UPDATE train_command_proposal
SET status = 'FAILED', error_code = #{errorCode}, executed_at = #{executedAt}
WHERE proposal_id = #{proposalId} AND status = 'EXECUTED' AND exit_code IS NULL
